args.sparql:
SELECT ?film ?filmLabel ?director ?directorLabel ?bd1 ?bd2 WHERE {
  VALUES ?film { dbr:Hum_Dil_De_Chuke_Sanam dbr:The_Greyhound_Limited }
  ?film dbo:director ?director .
  OPTIONAL { ?director dbo:birthDate ?bd1. }
  OPTIONAL { ?director dbp:birth_date ?bd2. }
  OPTIONAL { ?film rdfs:label ?filmLabel FILTER (lang(?filmLabel) = "en") }
  OPTIONAL { ?director rdfs:label ?directorLabel FILTER (lang(?directorLabel) = "en") }
}

SELECT ?film ?filmLabel ?director ?directorLabel ?birthDate WHERE {
  VALUES ?film { dbr:Hum_Dil_De_Chuke_Sanam dbr:The_Greyhound_Limited }
  ?film dbo:director ?director .
  OPTIONAL { ?director dbo:birthDate ?bd1. }
  OPTIONAL { ?director dbp:birth_date ?bd2. }
  BIND(COALESCE(?bd1, ?bd2) AS ?birthDateRaw)
  FILTER(bound(?birthDateRaw))
  BIND(xsd:date(str(?birthDateRaw)) AS ?birthDate)
  OPTIONAL { ?film rdfs:label ?filmLabel FILTER (lang(?filmLabel) = 'en') }
  OPTIONAL { ?director rdfs:label ?directorLabel FILTER (lang(?directorLabel) = 'en') }
}
ORDER BY DESC(?birthDate)
LIMIT 1

